import json, urllib.request
from playwright.sync_api import sync_playwright
prov=json.load(open('/tmp/prov.json')); B='http://localhost:8765/'; erros=[]; n=0
XLSX=open('/home/claude/testes/node_modules/xlsx/dist/xlsx.full.min.js').read()
def ok(m):
    global n; n+=1; print('ok ',m)
with sync_playwright() as p:
    br=p.chromium.launch(executable_path='/usr/bin/google-chrome', args=['--no-sandbox'])
    ctx=br.new_context(viewport={'width':1366,'height':900}, locale='pt-BR')
    ctx.route('**/cdnjs.cloudflare.com/**/xlsx.full.min.js', lambda rt: rt.fulfill(status=200, content_type='application/javascript', body=XLSX))
    pg=ctx.new_page()
    pg.on('pageerror', lambda e: erros.append('PAGEERR '+str(e)))
    pg.on('console', lambda m: erros.append(m.text) if m.type=='error' and 'ERR_FAILED' not in m.text else None)
    pg.add_init_script("try{localStorage.setItem('jornada_gas_url','http://localhost:8765/exec')}catch(e){}")
    pg.goto(B); pg.fill('#login-email','marques.marcela@estacio.br'); pg.fill('#login-senha',prov['admin']); pg.click('#btn-entrar')
    pg.wait_for_selector('#form-troca:not([hidden])'); pg.fill('#troca-atual',prov['admin']); pg.fill('#troca-nova','Admin2026b'); pg.fill('#troca-conf','Admin2026b'); pg.click('#form-troca button.primario')
    pg.wait_for_function("document.body.dataset.tela==='app'")
    pg.goto(B+'#/bases'); pg.wait_for_selector('#cards-bases .card-sistema', timeout=15000); pg.wait_for_timeout(1500)
    assert 'Estágio (relatório do BI)' in pg.inner_text('#cards-bases'); ok('Central de Bases tem o card do relatório do BI de estágio')
    pg.click('a[href="#/bases/estagio"]'); pg.wait_for_timeout(2000)
    fi=[x for x in pg.frames if 'sistema=estagio' in x.url and 'modo=importar' in x.url][0]; fi.wait_for_selector('#f-importar')
    fi.set_input_files('#f-arquivo','/home/claude/testes/estagio_bi_ficticio.xlsx'); fi.wait_for_function("Motor.estado.alunos.length===6", timeout=20000)
    ok('importa o relatório do BI: 7 linhas viram 6 alunos (disciplinas juntas por matrícula)')
    pg.goto(B+'#/bases'); pg.wait_for_timeout(2500); assert '6 alunos em 7 disciplinas' in pg.inner_text('#cards-bases').replace('\xa0',' '), pg.inner_text('#cards-bases'); ok('card mostra 6 alunos em 7 disciplinas')
    pg.goto(B+'#/s/estagio'); pg.wait_for_timeout(2500)
    f=[x for x in pg.frames if 'sistema=estagio' in x.url and 'modo=' not in x.url][0]; f.wait_for_function("Motor.estado.alunos.length===6", timeout=20000)
    assert f.locator('#f-importar').count()==0; ok('dentro do Estágio não há importação (só na Central)')
    cart=f.inner_text('.cartoes').upper()
    for k in ['SEM TCE · PRAZO VENCIDO','SEM TCE · NO PRAZO','TCE EM ANDAMENTO','TCE INDEFERIDO','DOCUMENTAÇÃO PENDENTE','DOCUMENTAÇÃO ENTREGUE','MATRÍCULA INDEVIDA']: assert k in cart, (k, cart)
    ok('cartões: sem TCE (vencido e no prazo), andamento, indeferido, documentação pendente e entregue, matrícula indevida')
    nome=f.inner_text('tr[data-mat="202301000100"]'); assert 'Engaja Exemplo 1' in nome and 'Sem TCE' in nome and 'matrícula indevida' in nome, nome; ok('nome vem da base líquida; disciplina indevida não esconde a que está sem TCE')
    assert 'vencido' in f.inner_text('tr[data-mat="202301000100"]'); ok('prazo do TCE vencido aparece em alerta')
    f.click('[data-card="nao_fora"]'); f.wait_for_timeout(300); assert f.locator('tr[data-mat]').count()==1; ok('cartão "Sem TCE · prazo vencido" filtra')
    f.click('[data-card="nao_fora"]'); f.wait_for_timeout(300)
    f.click('tr[data-mat="202301000100"] td.nome'); f.wait_for_selector('#modal:not([hidden])')
    assert 'ESTAGIO SUP. EXEMPLO II' in f.inner_text('#modal') and 'matrícula indevida' in f.inner_text('#modal'); ok('ficha mostra as disciplinas do BI')
    pg.screenshot(path='/home/claude/testes/tela_estagio_ficha.png')
    f.select_option('#m-resultado','Orientado a abrir o TCE') if f.locator('#m-resultado').count() else None
    obs=f.locator('#modal textarea').first; obs.fill('Orientado sobre o TCE pelo portal')
    fu=f.locator('#modal input[type=date]').first
    if fu.count(): fu.fill(__import__('datetime').date.today().isoformat())
    f.click('#modal button.primario'); f.wait_for_function("Object.values(Motor.estado.regs).length>=1", timeout=15000); ok('acionamento registrado pela ficha')
    f.evaluate("document.getElementById('modal').hidden=true")
    f.click('[data-aba=followup]'); f.wait_for_timeout(500); assert f.locator('[data-feito]').count()>=1; ok('follow-up aparece na aba')
    f.click('[data-aba=dashboard]'); f.wait_for_timeout(500); t=f.inner_text('#area'); assert 'Situação do TCE por curso' in t and 'Próximos prazos' in t, t[:300]; ok('dashboard: TCE por curso, modalidade, mudanças e próximos prazos')
    pg.screenshot(path='/home/claude/testes/tela_estagio_dash.png', full_page=True)
    f.click('[data-aba=produtividade]'); f.wait_for_timeout(500); assert 'Marcela' in f.inner_text('#area'); ok('produtividade mostra a atendente')
    br.close()
print(n,'passos ok'); print('erros:', erros or 'nenhum')
